# Generated by `cargo xtask generate-install-scripts`. Do not edit manually.
param(
    [string] $FromFile
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

$Product = "tclaude"

function Invoke-CurlDownload {
    param(
        [string] $Uri,
        [string] $Destination
    )

    $parsedUri = $null
    if (-not [System.Uri]::TryCreate($Uri, [System.UriKind]::Absolute, [ref]$parsedUri) -or
        $parsedUri.Scheme -notin @("http", "https")) {
        throw "download URL must use HTTP or HTTPS: $Uri"
    }

    $curl = Get-Command curl.exe -CommandType Application -ErrorAction SilentlyContinue |
        Select-Object -First 1
    if ($null -eq $curl) {
        throw "installation requires curl.exe, which is included with supported Windows versions"
    }

    $arguments = @(
        "--fail",
        "--silent",
        "--show-error",
        "--location",
        "--connect-timeout", "30",
        "--speed-limit", "1024",
        "--speed-time", "30"
    )
    if ($parsedUri.Scheme -eq "https") {
        $arguments += @("--proto", "=https", "--tlsv1.2")
    }
    $arguments += @("--output", $Destination, "--", $Uri)

    $curlOutput = & $curl.Source @arguments 2>&1
    $curlExitCode = $LASTEXITCODE
    if ($curlExitCode -ne 0) {
        $detail = ($curlOutput | ForEach-Object { $_.ToString() }) -join [Environment]::NewLine
        $message = "install: failed to download $Uri (curl exit code $curlExitCode)."
        if (-not [string]::IsNullOrWhiteSpace($detail)) {
            $message += " $detail"
        }
        throw $message
    }
}

function Publish-EnvironmentChange {
    if (-not ("TcliInstaller.EnvironmentNativeMethods" -as [type])) {
        Add-Type -Namespace TcliInstaller -Name EnvironmentNativeMethods -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("user32.dll", SetLastError = true, CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
public static extern System.IntPtr SendMessageTimeout(
    System.IntPtr hWnd,
    uint message,
    System.UIntPtr wParam,
    string lParam,
    uint flags,
    uint timeout,
    out System.UIntPtr result);
'@
    }

    $result = [UIntPtr]::Zero
    [TcliInstaller.EnvironmentNativeMethods]::SendMessageTimeout(
        [IntPtr]0xffff,
        0x1a,
        [UIntPtr]::Zero,
        "Environment",
        0x0002,
        1000,
        [ref]$result
    ) | Out-Null
}

function Test-PathEntry {
    param(
        [string] $PathValue,
        [Parameter(Mandatory)][string] $Dir
    )

    $entries = @($PathValue -split ";" | ForEach-Object { $_.Trim().TrimEnd('\') })
    return $entries -contains $Dir.TrimEnd('\')
}

function Add-UserPath {
    param([Parameter(Mandatory)][string] $Dir)

    $changed = $false
    $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
    if (-not (Test-PathEntry $userPath $Dir)) {
        $entries = @($userPath -split ";" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
        [Environment]::SetEnvironmentVariable("Path", (($entries + $Dir) -join ";"), "User")
        $changed = $true
    }

    if (-not (Test-PathEntry ([Environment]::GetEnvironmentVariable("Path", "Process")) $Dir)) {
        $env:Path = "$Dir;$env:Path"
    }

    if ($changed) {
        try {
            Publish-EnvironmentChange
        }
        catch {
            Write-Warning "install: could not broadcast PATH change: $($_.Exception.Message)"
        }
        Write-Host "install: added $Dir to the user PATH"
    }
}

function Resolve-UpdateBase {
    $override = [Environment]::GetEnvironmentVariable("TCLAUDE_UPDATE_BASE")
    $base = if ([string]::IsNullOrWhiteSpace($override)) {
        "https://mirrors.tencent.com/repository/generic/tclaude"
    } else {
        $override
    }
    return "$($base.TrimEnd('/'))/$Product/"
}

function Get-RemoteVersion {
    param([Parameter(Mandatory)][string] $Base)

    $tmp = [IO.Path]::GetTempFileName()
    try {
        foreach ($name in @("LAST_VERSION", "VERSION")) {
            try {
                Invoke-CurlDownload -Uri "${Base}${name}" -Destination $tmp
                $version = (Get-Content -LiteralPath $tmp -Raw).Trim()
                if (-not [string]::IsNullOrWhiteSpace($version)) {
                    return $version
                }
            }
            catch {
                Write-Verbose "install: ${Base}${name} unavailable: $($_.Exception.Message)"
            }
        }
        throw "failed to fetch ${Base}LAST_VERSION or ${Base}VERSION"
    }
    finally {
        if (Test-Path -LiteralPath $tmp -PathType Leaf) {
            Remove-Item -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
        }
    }
}

function Build-ArtifactUrl {
    param(
        [Parameter(Mandatory)][string] $Base,
        [Parameter(Mandatory)][string] $Version
    )

    return "${Base}${Version}/$Product-$Version-windows-x64.exe"
}

if ($env:OS -ne "Windows_NT") {
    Write-Error "install.ps1 supports Windows only. Use install.sh on Linux or macOS."
    exit 1
}

$localAppData = [Environment]::GetEnvironmentVariable("LOCALAPPDATA")
if ([string]::IsNullOrWhiteSpace($localAppData)) {
    $localAppData = [Environment]::GetFolderPath([Environment+SpecialFolder]::LocalApplicationData)
}
if ([string]::IsNullOrWhiteSpace($localAppData)) {
    throw "LOCALAPPDATA is not available"
}

$installDir = Join-Path $localAppData "tcli\bin"
$dest = Join-Path $installDir "$Product.exe"
New-Item -ItemType Directory -Force -Path $installDir | Out-Null

$tmp = Join-Path $installDir ".${Product}.$([IO.Path]::GetRandomFileName()).tmp"

try {
    if (-not [string]::IsNullOrWhiteSpace($FromFile)) {
        if (-not (Test-Path -LiteralPath $FromFile -PathType Leaf)) {
            throw "not a file: $FromFile"
        }
        Write-Host "install: installing from $FromFile"
        Copy-Item -LiteralPath $FromFile -Destination $tmp -Force
    }
    else {
        $arch = [Environment]::GetEnvironmentVariable("PROCESSOR_ARCHITEW6432")
        if ([string]::IsNullOrWhiteSpace($arch)) {
            $arch = [Environment]::GetEnvironmentVariable("PROCESSOR_ARCHITECTURE")
        }
        if ($arch -notmatch "^(?i:AMD64|x86_64)$") {
            throw "unsupported Windows architecture: $arch"
        }
        $base = Resolve-UpdateBase
        $version = Get-RemoteVersion -Base $base
        $url = Build-ArtifactUrl -Base $base -Version $version
        Write-Host "install: downloading $url"
        Invoke-CurlDownload -Uri $url -Destination $tmp
    }
    if (-not (Test-Path -LiteralPath $tmp -PathType Leaf)) {
        throw "artifact was not created"
    }
    if ((Get-Item -Force -LiteralPath $tmp).Length -eq 0) {
        throw "artifact is empty"
    }
    Move-Item -Force -LiteralPath $tmp -Destination $dest
    $tmp = $null

    & $dest --help *> $null
    if ($LASTEXITCODE -ne 0) {
        throw "installed binary failed verification: $dest --help"
    }
}
catch {
    Write-Error "install: $($_.Exception.Message)"
    exit 1
}
finally {
    if ($tmp -and (Test-Path -LiteralPath $tmp -PathType Leaf)) {
        Remove-Item -Force -LiteralPath $tmp -ErrorAction SilentlyContinue
    }
}

Write-Host "install: installed $Product to $dest"
try {
    Add-UserPath $installDir
}
catch {
    Write-Warning "install: could not update the user PATH: $($_.Exception.Message)"
}
Write-Host "install: done. run ``$Product --help`` to get started"
